<?php require __DIR__.'/db.php';require __DIR__.'/functions.php';$tables=['ulyses'=>'ULYSES','was'=>'WAS','unoau'=>'UnoAUno'];$exists=[];foreach($tables as $t=>$label){try{$pdo->query('SELECT 1 FROM '.qi($t).' LIMIT 1');$exists[$t]=true;}catch(Throwable $e){$exists[$t]=false;}}$doc=normdoc($_GET['documento']??'');$data=[];if($doc!==''){foreach($tables as $t=>$label){if($exists[$t]){$s=$pdo->prepare('SELECT * FROM '.qi($t).' WHERE `__documento_normalizado`=? LIMIT 100');$s->execute([$doc]);$data[$t]=$s->fetchAll();}}}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cruce</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><a class="btn btn-outline-secondary btn-sm mb-3" href="index.php">← Inicio</a><h1 class="h3">Cruce por identificación</h1><form class="card card-body my-3" method="get"><label class="form-label">Documento</label><div class="input-group"><input class="form-control" name="documento" value="<?=h($_GET['documento']??'')?>" required><button class="btn btn-primary">Buscar</button></div></form><?php if($doc!==''):foreach($tables as $t=>$label):?><section class="card card-body mb-3"><h2 class="h5"><?=h($label)?></h2><?php if(!$exists[$t]):?><p>Fuente aún no importada.</p><?php elseif(empty($data[$t])):?><p>Sin coincidencias.</p><?php else:?><div class="table-responsive"><table class="table table-sm table-bordered"><thead><tr><?php foreach(array_keys($data[$t][0]) as $c):?><th><?=h($c)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($data[$t] as $row):?><tr><?php foreach($row as $v):?><td><?=h($v)?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endforeach;endif;?></main></body></html>
